import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 1, False), event("c", 2, None)], "c": []}
    assert pooled_flag_rate(groups) == 1 / 3
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_flags_in_window_boundaries():
    assert flags_in_window([2, 3, 4], 0) == 0
    assert flags_in_window([2, 3, 4], 2) == 7
    assert flags_in_window([2, 3, 4], 4) == 9


def test_parse_transcript_log_skips_and_strips():
    lines = ["", " \t\n", "  # comment", " x , 2 , 0 ", "y,3,  ", "z, 4, 1"]
    assert parse_transcript_log(lines) == [event("x", 2, False), event("y", 3, None), event("z", 4, True)]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,1,1", "x,today,1"])
def test_parse_transcript_log_reports_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log([" # header", "a,1,1", "", bad_line])


def test_dedupe_transcripts_last_duplicate_wins_before_sort():
    old, new = event("b", 5, True), event("b", 2, False)
    a, z = event("a", 2, None), event("z", 1, True)
    assert dedupe_transcripts([old, a, z, new]) == [z, a, new]


def test_daily_flag_counts_inclusive_and_zero_filled():
    events = [event("a", 0, True), event("b", 1, True), event("c", 1, True),
              event("d", 3, None), event("e", 4, True), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 5, True), event("c", 6, False)], "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"a": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_orders_ties_and_excludes_empty():
    groups = {"b": [event("b", 1, False)], "empty": [], "z": [event("z", 1, True)], "a": [event("a", 1, None)]}
    assert top_flagged_groups(groups, 2) == ["z", "a"]
    assert top_flagged_groups(groups, 8) == ["z", "a", "b"]


def test_flag_rate_by_group_sorted_with_empty_group():
    groups = {"c": [event("c", 1, True)], "a": [], "b": [event("b", 2, None)]}
    assert list(flag_rate_by_group(groups).items()) == [("a", None), ("b", 0.0), ("c", 1.0)]


def test_longest_flag_streak_resets_on_nonpositive_entries():
    assert longest_flag_streak([1, 2, 0, 1, -1, 1]) == 2
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0

